import{randomUUID}from"node:crypto";import{mkdir,rm}from"node:fs/promises";import{join}from"node:path";async function createDevelopmentHostWorkspace(e){let t=join(e,`.eve`,`dev-hosts`,randomUUID()),n={artifactsDir:join(t,`artifacts`),compilerArtifactsDir:join(t,`compiler`),nitroBuildDir:join(t,`nitro`),nitroOutputDir:join(t,`output`),rootDir:t,workflowBuildDir:join(t,`workflow`)};return await mkdir(t,{recursive:!0}),n}async function removeDevelopmentHostWorkspace(e){await rm(e.rootDir,{force:!0,recursive:!0})}export{createDevelopmentHostWorkspace,removeDevelopmentHostWorkspace};